      "id": "LLM-0091",
      "type": "technical",
      "question": "微调和 RAG 的场景区别，SFT 和 RLHF",
      "topic": [
        "llm",
        "finetune",
        "rag"
      ],
      "difficulty": 3,
      "frequency": "low",
      "source_type": "ai_generated",
