      "id": "PROJECT-0282",
      "type": "project",
      "question": "Iceberg为什么适合湖仓架构？",
      "difficulty": 0,
      "topic": [
        "面试宝典"
      ],
      "source_type": "knowledge",
      "frequency": "",
